<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('Administrator','IT');$pageTitle='Roles & Permissions';$roles=db()->query('SELECT r.*,COUNT(rp.permission_id) permission_count FROM roles r LEFT JOIN role_permissions rp ON rp.role_id=r.id GROUP BY r.id ORDER BY r.name')->fetchAll();$perms=db()->query('SELECT * FROM permissions ORDER BY name')->fetchAll();require __DIR__.'/../../includes/header.php';?><div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content"><div class="admin-top"><div><div class="eyebrow">Access control</div><h1 class="admin-title">Roles & permissions</h1><p class="kicker">Layered authorization follows account status → role → permission → business rule.</p></div></div><div class="split"><div class="panel table-wrap"><table class="table"><thead><tr><th>Role</th><th>Description</th><th>Permissions</th></tr></thead><tbody><?php foreach($roles as $r):?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['description'])?></td><td><?=e($r['permission_count'])?></td></tr><?php endforeach;?></tbody></table></div><div class="panel"><div class="eyebrow">Permission catalogue</div><?php foreach($perms as $p):?><span class="tag" style="margin:3px"><?=e($p['name'])?></span><?php endforeach;?></div></div></section></div><?php require __DIR__.'/../../includes/footer.php';?>
